scwin.checkValue = function() {
    var data = ((j) => j.length ? j : $('#mf_grid1_body_tbody tr>td:nth-child(3)'))($('#grid1_body_tbody tr>td:nth-child(3)'));
    for (i = 0; i < data.length; i++) {
        if (data[i].innerText != "1" && data[i].innerText != "2") {
            return false;
            break;
        }
    }
    return true;
}
scwin.checktype = function() {
    return typeof (document.getElementById('grid1_header_category1_filter') || document.getElementById('mf_grid1_header_category1_filter')) === 'object';
}
